export const ribbonMatchPages=['make','name','kept'];
const rows=[
 ['half-quarters','Two labels for one ribbon',1,2,4,'Mark the same amount using quarters.','The market display needs a second label for a half-ribbon decoration.'],
 ['quarters-half','Join the quarter pieces',2,4,2,'Mark the same amount using halves.','The market label names two quarters. Make that amount with larger equal parts.'],
 ['third-sixths','Split a third',1,3,6,'Mark the same amount using sixths.','A third-ribbon strip marks the reading corner. Find its length using smaller equal parts.'],
 ['thirds-sixths','Two thirds, smaller pieces',2,3,6,'Mark the same amount using sixths.','The plant table needs the length pictured by two thirds of our model ribbon.'],
 ['sixths-third','Join two sixths',2,6,3,'Mark the same amount using thirds.','The market sign has two sixths marked. Find the same length in thirds.'],
 ['sixths-thirds','Join four sixths',4,6,3,'Mark the same amount using thirds.','The flower stall has four sixths marked. Keep that length while changing its label.'],
];
export const ribbonMatchCases=rows.map(([id,title,referenceNumerator,referenceDenominator,workingDenominator,request,story])=>{const wanted=referenceNumerator*workingDenominator/referenceDenominator;return {version:1,id,title,story,request,namingPrompt:'What numerator names our working flag?',referenceNumerator,referenceDenominator,workingDenominator,unitTicks:12,wholeLength:12,wholeWidth:1,drawingVersion:1,referencePictureText:`The fixed whole is divided into ${referenceDenominator} equal parts. Its first ${referenceNumerator} ${referenceNumerator===1?'part is':'parts are'} selected from zero, with the fixed flag at ${referenceNumerator}/${referenceDenominator}. The working whole has exactly the same length and width.`,help:`Both whole ribbons have the same length, width and scale. The fixed reference is ${referenceNumerator}/${referenceDenominator}. The working ribbon has ${workingDenominator} equal parts; ${wanted} of those parts reach the same endpoint: ${referenceNumerator}/${referenceDenominator} = ${wanted}/${workingDenominator}. Adding cuts does not add ribbon. The numerator is the top number: count selected equal parts from zero, not boundary marks. Name the actual working flag even if it has not reached the reference. The partition and reference are supplied; a matching construction or supplied numerator choice does not establish independent drawing, notation writing or explanation.`};});
export const ribbonMatchSource=id=>{const s=ribbonMatchCases.find(s=>s.id===id);return s?structuredClone(s):null;};
